			double adjustedLower = Math.max(0.0d, base.lowerRows() - mutationDeletions);
			double adjustedUpper = saturatedAdd(base.upperRows(), mutationInsertions);
			double adjustedPoint = Math.max(adjustedLower, Math.min(adjustedUpper, base.pointRows()));
			FrontierLeafEstimate scalar = new FrontierLeafEstimate(adjustedPoint, adjustedLower, adjustedUpper,
					Math.min(base.confidence(), 0.5d), "frontier-v2-omni-plus-mutation-bound",
					FrontierFallbackReason.NONE);
